      "detail": "粽角榫用于三面平（如茶几、方凳）的三方格角结合，三个方向各出45°格角，合成如粽子尖角般的六条斜线，外观清爽且结构稳定。因三根材在角部交汇，对角度与精度要求极高。\n粽角榫将三根木料端头均裁成 45° 斜角，内部再挖榫卯相互咬合，于直角转角相遇；外观如粽子尖角。柜类、匣类顶角常见，表面简洁而做工极复杂。",
      "traits": [
        "三面平家具的三方格角结合",
        "六条45°格角线合成“粽子角”",
        "角部三材交汇，对精度要求极高",
        "三根材端均做 45° 格角，内部再出榫卯咬合",
        "外观呈粽子尖角，六条 45° 斜线交汇",
        "多用于高档柜匣顶角；外观简练、工艺极难"
      ],
      "enDetail": "Used on flush three-sided pieces (stools, stands): three members meet with six 45° miters, reading as a crisp ‘zong’ tip. Dimensional accuracy is unforgiving because three axes converge at one point.",
      "illus": "data/illus/zongjiao.png",
      "illusStyle": "photo"
