      "detail": "插肩榫与夹头榫用途相近，用于案类。其腿足前脸做出斜肩，与牙板正面的槽口相插，肩部如刀插般没入牙板，外观更简练。与夹头榫“开口夹住”不同，插肩榫强调“插入”。\n插肩榫主要用于腿足与牙板连接：腿足出榫，外侧削成斜肩；牙板端头做相应斜口包夹斜肩，形成强度高、过渡流畅的节点，转角常呈 V 形包口。无束腰案形结体家具常用。\n插肩榫见于案形结体：腿足上端出榫，外侧削成斜肩；牙条端头开相应斜口插合包夹，装配后转角常见 V 形包肩线。结构与观感兼顾，是无束腰案类的典型节点。",
